#!/bin/bash
# Run from the folder containing the src files
cd "$(dirname "$0")" && { SPR="${REPO:-/home/claude/rla-sharp}/data/nba_spreads.json"; [ -f "$SPR" ] && python3 tools/nbaspr.py "$SPR" > nba_spr.js || [ -f nba_spr.js ] || echo "const NBA_SPR={};" > nba_spr.js; } && { [ -f nba_espn.js ] || echo "const NBA_ESPN={games:[],logs:[]};" > nba_espn.js; } && { [ -f nhl_data.js ] || echo 'var NHL_GEN="",NHL_DATE="",NHL_TOM="",NHL_SLATE=[],NHL_NEXT=[],NHL_LATER=[],NHL_TEAM={},NHL_RES=[],NHL_P={},NHL_G={},NHL_INJ={},NHL_H2HP={},NHL_LZ=[],NHL_MODEL=null,NHL_PRES=[],NHL_PRES_D=null,NHL_RECENT=[],NHL_PROPS=[],NHL_FOM={};' > nhl_data.js; } && { [ -f track_data.js ] || echo 'var TRACK=null;' > track_data.js; } && { [ -f nba_refs.js ] || echo 'var NBA_REFS=null;' > nba_refs.js; } && { [ -f nfl_qtr.js ] || echo 'var NFL_QTR={};' > nfl_qtr.js; } && { [ -f soccer_data.js ] || echo "/* soccer data not built yet */ var SOC_OK=0;" > soccer_data.js; } && { ls soccer_p_*.js >/dev/null 2>&1 || [ -f soccer_players.js ] || echo "var SOC_P={};var SOC_P_OK=1;" > soccer_players.js; } && { [ -f nfl_box.js ] || echo "var BOX_ESPN={};" > nfl_box.js; } && { [ -f nfl_weekly.js ] || echo "var NFLW=null;" > nfl_weekly.js; } && { [ -f nfl_logs.js ] || echo "var NFLV_LOGS=null;" > nfl_logs.js; } && { [ -f nba_lu.js ] || echo "var NBA_LU=null;" > nba_lu.js; } && { [ -f nfl_wx.js ] || echo "var NFL_WX=null;" > nfl_wx.js; } && { [ -f nfl_refs.js ] || echo "var NFL_REFS=null;" > nfl_refs.js; } && { [ -f nhl_lines.js ] || echo "var NHL_LINES=null;" > nhl_lines.js; } && { [ -f nba_next_lines.js ] || echo "var NBA_LINES_NEXT={};" > nba_next_lines.js; } && { [ -f nfl_next_lines.js ] || echo "var NFL_LINES_NEXT={};" > nfl_next_lines.js; } && { [ -f soccer_mgr.js ] || echo "var SOC_MGR={};" > soccer_mgr.js; } && { [ -f nfl_x2.js ] || echo 'var NFL_RZ={},NFL_RZT={},NFL_LOC={},NFL_DLOC={},NFL_QBRUN={},NFL_QBV={},NFL_PROE={},NFL_DIVX=null,NFL_DIVG=[],NFL_K={};' > nfl_x2.js; } && python3 tools/linehist.py "${REPO:-/home/claude/rla-sharp}" > lines_hist.js && echo '/* NHL data loads on demand from nhl_data.js (next to index.html) */ var NHL_GEN="",NHL_DATE="",NHL_TOM="",NHL_SLATE=[],NHL_NEXT=[],NHL_LATER=[],NHL_TEAM={},NHL_RES=[],NHL_P={},NHL_G={},NHL_INJ={},NHL_H2HP={},NHL_LZ=[],NHL_MODEL=null,NHL_PRES=[],NHL_PRES_D=null,NHL_RECENT=[],NHL_PROPS=[],NHL_FOM={};' > nhl_stub.js && echo "var BUILD_AT=\"$(date -u +%Y-%m-%dT%H:%M:%SZ)\";" >> nhl_stub.js && python3 tools/splitnba.py nba_data.js && python3 tools/lighttheme.py shell_head.html > shell_built.html && sed -i "s/__BUILDV__/$(grep -o 'BUILD_AT="[^"]*"' nhl_stub.js | tr -dc 0-9)/" shell_built.html && cat shell_built.html real.js pfr.js h2h_notes.js plogs.js plogs2.js posv.js qb1.js engine.js dataview.js nfl_wx.js nfl_refs.js nhl_lines.js nba_next_lines.js nfl_next_lines.js soccer_mgr.js inj.js usage_data.js usage.js market.js adv_data.js nfl_box.js nfl_weekly.js nfl_logs.js adv.js plays.js bets.js calc.js nba_data_core.js nba_lu.js nba_spr.js nba_espn.js nba_refs.js nba.js nfl_extra.js nfl_tgt.js nfl_rush.js nfl_qtr.js nfl_x2.js nhl_stub.js nhl.js soccer.js xsport.js track_data.js nflx.js nflteam.js propx.js live.js liveodds.js finals.js fresh.js ux.js xana.js extras.js app.js parlay.js facts.js factors.js without.js visuals.js gamepage.js news.js week.js potd.js h2hbox.js ui.js > index.html && { [ -f tools/jsonify.py ] && python3 tools/jsonify.py index.html || true; } && echo "built index.html ($(wc -c < index.html) bytes)"
